    /// strip for the changed file, at the old length — a longer file's
    /// tail is HELD below.
    static func thumbnailSeconds(for media: MediaSnapshot) -> Int {
        max(
            1,
            min(maxThumbnails, Int((Double(media.duration) / Double(ReelTime.perSecond)).rounded(.up))))
